// Junta las dos senales de salud de los scrapers:
//   sin_captura  -> corren pero no capturan (parser roto) en fuentes de contenido garantizado
//   parados      -> no se ejecutan (cron caido) — cubre tambien las nacionales tipo wegow
const sinCaptura = ($('Detectar Scrapers Mudos').all() || []).map(i => i.json).filter(x => x.fuente);
const parados    = ($('Detectar Parados').all() || []).map(i => i.json).filter(x => x.workflow);

if (sinCaptura.length === 0 && parados.length === 0) {
  return [];   // nada que avisar: el workflow muere aqui
}

const filaCap = (f) => {
  const sil = f.dias_en_silencio == null ? 'NUNCA ha capturado'
            : `${f.dias_en_silencio} dias sin leer (umbral ${f.umbral_dias})`;
  return `<tr><td style="padding:6px 12px;border-bottom:1px solid #eee"><b>${f.fuente}</b></td>
    <td style="padding:6px 12px;border-bottom:1px solid #eee">${f.ultima_lectura||'-'}</td>
    <td style="padding:6px 12px;border-bottom:1px solid #eee">${sil}</td></tr>`;
};
const filaPar = (p) => `<tr><td style="padding:6px 12px;border-bottom:1px solid #eee"><b>${p.workflow}</b></td>
    <td style="padding:6px 12px;border-bottom:1px solid #eee">${p.ultima_ejecucion||'nunca'}</td>
    <td style="padding:6px 12px;border-bottom:1px solid #eee">${p.dias_parado==null?'sin ejecuciones':p.dias_parado+' dias parado'}</td></tr>`;

let html = '';
if (parados.length) {
  html += `<h3>Scrapers PARADOS (no se ejecutan)</h3>
  <p>Estos workflows estan activos pero llevan sin ejecutarse mas de lo normal:
  probablemente el cron se detuvo o el workflow se toco.</p>
  <table style="border-collapse:collapse;font-family:sans-serif;font-size:14px">
  <tr style="background:#f5f5f5"><th style="padding:6px 12px;text-align:left">Workflow</th>
  <th style="padding:6px 12px;text-align:left">Ultima ejecucion</th>
  <th style="padding:6px 12px;text-align:left">Estado</th></tr>
  ${parados.map(filaPar).join('')}</table>`;
}
if (sinCaptura.length) {
  html += `<h3>Scrapers SIN CAPTURAR (corren pero no leen)</h3>
  <p>Fuentes de contenido garantizado que terminan en success pero llevan sin
  capturar nada: probablemente el origen cambio el HTML y el parser saca 0.</p>
  <table style="border-collapse:collapse;font-family:sans-serif;font-size:14px">
  <tr style="background:#f5f5f5"><th style="padding:6px 12px;text-align:left">Fuente</th>
  <th style="padding:6px 12px;text-align:left">Ultima lectura</th>
  <th style="padding:6px 12px;text-align:left">Silencio</th></tr>
  ${sinCaptura.map(filaCap).join('')}</table>`;
}
html += `<p style="color:#666;font-size:12px">Nacionales que capturan 0 de forma legitima (wegow, etc.):
vigila_captura=false en promotores_configuracion, solo se vigilan por ejecucion.</p>`;

const n = parados.length + sinCaptura.length;
return [{ json: {
  emailSubject: `[C15] ${n} scraper(s) con problemas (${parados.length} parados, ${sinCaptura.length} sin capturar)`,
  emailBodyHtml: html }}];
